-- D-23 Allergen Management Program, DRAFT:
--   FSQM-027 Allergen Management Program
--   FRM-916  Allergen Cleaning Verification Record
--
-- Five Minor findings: 2.8.1.1, .2, .3, .5, .6. FSQM-027 is reserved in the remediation workbook; FRM-916
-- is the next free number in the 900 block (sanitation and GMP).
--
-- Owner's answers, 2026-10-05: allergens on site are wheat, milk, egg, soy, pecans and other tree nuts;
-- nut cakes are made last in the day; the changeover clean is checked by looking only; staff eat in a
-- separate break area. Every cake declares wheat, milk, egg and soy, so tree nuts are the one allergen
-- that can cross between products - the program is built around that.
--
-- The plan asked for SOP-204 to be revised and the Allergen Changeover Log renumbered. Neither is done,
-- on purpose: SOP-204 is a three-line draft that was never issued, and the changeover clean is already
-- written per machine in SOP-901..904 and recorded on FRM-909..912 (each has an "Allergen changeover"
-- tick). There is no changeover log to renumber; FRM-204 stays the supplier evaluation checklist.
-- SOP-204 is left untouched here and archived when FSQM-027 is issued, in one transaction (the
-- FSQM-012 / SOP-11.3 pattern). 2.8.1.4 was scored Compliant against SOP-204, so FSQM-027 cites it.
--
-- What is new for the site: allergen-specific swabs (2.8.1.5). ATP and a visual check do not show an
-- allergen is gone. FRM-916 records validation (three cleans per machine) and three-monthly verification.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-027', 'FRM-916')) then
    raise exception 'a D-23 document number is already in use.';
  end if;
  if (select count(distinct sop_number) from public.sop_documents
       where sop_number in ('FSQM-004', 'FSQM-009', 'FSQM-012', 'FSQM-016', 'FSQM-018', 'FSQM-019', 'FSQM-023', 'SOP-2.2.3', 'SOP-2.3.2', 'SOP-2.3.2.3', 'SOP-2.3.4', 'SOP-901', 'SOP-902', 'SOP-903', 'SOP-904', 'TRN-003', 'TRN-004', 'TRN-004A', 'FRM-007', 'FRM-207', 'FRM-301', 'FRM-601', 'FRM-701', 'FRM-702', 'FRM-903', 'FRM-906', 'FRM-909', 'FRM-910', 'FRM-911', 'FRM-912', 'FRM-913') and status in ('active', 'draft')) <> 31 then
    raise exception 'a document D-23 names is missing: %', (
      select string_agg(n, ', ') from unnest(array['FSQM-004', 'FSQM-009', 'FSQM-012', 'FSQM-016', 'FSQM-018', 'FSQM-019', 'FSQM-023', 'SOP-2.2.3', 'SOP-2.3.2', 'SOP-2.3.2.3', 'SOP-2.3.4', 'SOP-901', 'SOP-902', 'SOP-903', 'SOP-904', 'TRN-003', 'TRN-004', 'TRN-004A', 'FRM-007', 'FRM-207', 'FRM-301', 'FRM-601', 'FRM-701', 'FRM-702', 'FRM-903', 'FRM-906', 'FRM-909', 'FRM-910', 'FRM-911', 'FRM-912', 'FRM-913']) n
       where not exists (select 1 from public.sop_documents d where d.sop_number = n and d.status in ('active', 'draft')));
  end if;
  -- the four machine logs must still carry the changeover tick the program points at
  if (select count(*) from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
                           jsonb_array_elements(s->'fields') f
       where d.sop_number in ('FRM-909', 'FRM-910', 'FRM-911', 'FRM-912') and d.status = 'active' and f->>'id' = 'allergen_change') <> 4 then
    raise exception 'a machine cleaning log no longer has its allergen changeover tick.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-027', 'Allergen Management Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '2.8.1.1, 2.8.1.2, 2.8.1.3, 2.8.1.4, 2.8.1.5, 2.8.1.6', true, $q${"purpose": "This program states how Adventure Bakery keeps an allergen out of any product that does not declare it: which allergens are on site, where they are kept, the order products are made in, the clean between them, and how that clean is proved.", "scope": "Every ingredient, processing aid and lubricant, every product made on site, and everyone who enters the production and storage rooms.", "definitions": "Allergen: one of the nine major food allergens listed in this program.\nCross-contact: an allergen getting into a product that does not contain it.\nChangeover: going from a product that contains an allergen to a product that does not declare it.\nChangeover clean: the full clean of everything the first product touched, done before the second product.\nValidation: proving once that the clean removes the allergen.\nVerification: checking, each time and at intervals, that the clean was done and still works.", "responsibility": "SQF Practitioner - carries out the risk analysis, keeps the allergen list and this program current, plans the swabs and decides what is done with a failed result. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nSenior Site Management - approves new materials, products and labels, and sets the production order.\nProduction staff - follow the production order, keep nuts apart, do and record the changeover clean, and report anything that goes wrong.\nAll staff - keep food in the break area and wash hands on entering production.", "procedure": ["The allergens", "• The list used is the nine major food allergens of the United States, where the product is made and sold: milk, egg, fish, crustacean shellfish, tree nuts, peanuts, wheat, soy and sesame (SQF 2.8.1.1 iii).", "• On this site: wheat, milk, egg, soy and tree nuts. Not on this site, and not brought in without this program being revised first: peanuts, sesame, fish and crustacean shellfish.", "• The list of allergens, and which materials and products carry each one, is posted in the production room and is in the Team Portal: the allergens of every material are on its FRM-207 entry (SQF 2.8.1.1 iv).", "The risk analysis", "• The SQF Practitioner assesses every raw material, ingredient and processing aid, and every lubricant that could touch product, for the allergens it contains or may contain. The record is the material's FRM-207 entry, taken from the manufacturer's label or specification (SQF 2.8.1.1 i).", "• What the analysis found:", "◦ Wheat, milk, egg and soy are in the cake base, the egg, the oil and the pan release spray. Every cake made here contains all four and declares all four, so they cannot make one cake unsafe for a person who can eat another. The risk is the label, not cross-contact.", "◦ Tree nuts are in some cakes and not in others. Pecans are the main one. This is the allergen that can cross from one product to another, on the mixer, the depositor, the pans, the racks, the dipping and packing tables, utensils, hands and clothing. It is the risk this program is built around.", "◦ Each tree nut is its own allergen on a label. A cake with one nut made after a cake with a different nut is a changeover, the same as a cake with no nuts.", "◦ Processing aid: the pan release spray contains soy, which every cake already declares.", "◦ Lubricants: the food-grade grease and oil used on the depositor and the mixer are assessed from the manufacturer's allergen statement, kept with the material's FRM-207 entry.", "◦ A new material, a new brand of an existing material, or a new product is assessed before it is used (SOP-2.3.2, SOP-2.3.4).", "Allergens brought in by people", "• Staff food, drink and bags are kept and eaten only in the break area, which is separate from the production and storage rooms. Nothing is eaten or drunk in production (FSQM-012).", "• Hands are washed on entering the production room and after eating. Outer clothing worn in production is not worn in the break area while eating.", "• Visitors and contractors agree to the same rules on the entrance screen before they go in (FRM-906), and bring no food past reception.", "• There is no vending machine on site. Peanuts and peanut products are the allergen most likely to arrive in a lunch; the hand wash and the break area rule are the control (SQF 2.8.1.1 ii).", "Receiving and storing", "• At receipt the brand and product are checked against FRM-207 on FRM-301. A different brand is a new material: its allergen statement, including any \"may contain\", is checked before it is used (SOP-2.3.4).", "• Nuts are kept in closed, labelled containers on the allergen rack in the production room, below other materials and never above them. An opened pack is resealed or put in a lidded container labelled with the product and the word NUTS.", "• Nuts have their own scoop and container, marked and used for nothing else. A spill is cleaned up at once.", "• Segregation is checked every production day on FRM-903 (\"Allergen controls / segregation followed\") and every month in the GMP inspection on FRM-913 (SQF 2.8.1.3).", "Making product - the changeover rule", "• Cakes without nuts are made first. Cakes with nuts are made last in the day, and the full clean follows them.", "• A changeover clean is done before any product that does not declare an allergen the product before it contained. On this site that means: after a nut cake and before a cake without that nut (SQF 2.8.1.6).", "• The changeover clean is the full clean in each machine's cleaning procedure - SOP-901 for the mixer, SOP-902 and SOP-903 for the depositors, SOP-904 for the kettle - and covers everything else the product touched: pans, racks, tables, scoops and utensils. It removes all visible residue from every product contact surface (SQF 2.8.1.4).", "• It is recorded on that machine's cleaning log - FRM-909, FRM-910, FRM-911 or FRM-912 - with \"Allergen changeover\" ticked and the line \"every food contact surface checked under good light\" completed.", "• Aprons and gloves are changed and hands washed after handling nuts and before handling a product without them.", "• Rework: a unit whose seal failed is re-pouched as the same product only. Product is never reworked into a different product (FSQM-019).", "• Labels: the allergens on every label are approved on FRM-601 and the label applied is checked at release on FRM-701 (SOP-2.3.2.3). The statement that the product was packaged in a facility that processes nuts does not replace the changeover clean.", "• These controls are carried into the food safety plan: the allergen hazards at each step are in FSQM-016 Part 7 (SQF 2.8.1.1 v, vi).", "Proving the clean works", "• Looking at a surface does not prove that an allergen is gone. The changeover clean is validated and verified with a test kit that detects the nut that was run, recorded on FRM-916 (SQF 2.8.1.5).", "• Validation: for each machine, the first three changeover cleans after a nut cake are swabbed after cleaning and before the next use. All three must show nothing detected. Until they do, a cake without nuts is not made on that machine after a nut cake.", "• Verification: every changeover clean is inspected under good light and recorded on the machine's cleaning log. In addition, one changeover clean on each machine is swabbed at least every three months.", "• The clean is validated again when the cleaning method, the detergent, the equipment, or the nut changes.", "• If a swab detects the allergen: the surface is cleaned and swabbed again, nothing is made on it until it passes, any product made since the last passing check is held on FRM-702 under FSQM-018, and a CAPA is raised on FRM-007.", "If something goes wrong", "• A nut found in or on a product that does not declare it, a wrong label, or a clean that was missed: stop, hold the product on FRM-702, and tell the SQF Practitioner. If product has left the site, FSQM-023 starts.", "Instruction", "• All staff complete the allergen training modules in the Team Portal (TRN-003, TRN-004 and TRN-004A) when they start and as they come due. Whoever receives, stores or handles nuts is shown this program and the changeover rule on the floor. The Team Portal keeps the record (SQF 2.8.1.2).", "Review", "• The SQF Practitioner reviews this program at least once a year, and before a new allergen, material or product is brought in. The review is recorded as a revision of this document.", "Records", "• FRM-207, FRM-301, FRM-903, FRM-913, the cleaning logs FRM-909 to FRM-912, FRM-916 and FRM-007 are kept as SOP-2.2.3 requires."], "form_references": "FRM-916 - Allergen Cleaning Verification Record\nFRM-909 - Mixer Cleaning & Pre-Use Check Log\nFRM-910 - Kook-E-King Depositor Cleaning & Pre-Use Check Log\nFRM-911 - Depositor Cleaning & Pre-Use Check Log (Beldos 275)\nFRM-912 - Kettle Cleaning & Pre-Use Check Log (Groen TDB)\nFRM-207 - Material Specification Register\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record\nFRM-913 - GMP / Food Safety Inspection Record\nFRM-601 - Label Review & Approval Form\nFRM-701 - Finished Product Release Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "records": "• FRM-916 - one per validation or verification swab session\n• The machine cleaning logs, FRM-909 to FRM-912, with the allergen changeover ticked\n• FRM-207 - the allergens of every material\n• FRM-903 and FRM-913 - segregation checks\n• Training records for TRN-003, TRN-004 and TRN-004A in the Team Portal", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.8.1.1, 2.8.1.2, 2.8.1.3, 2.8.1.4, 2.8.1.5, 2.8.1.6 (Allergen Management).\n\nSOP-901, SOP-902, SOP-903, SOP-904 - the cleaning procedure for each machine.\nSOP-2.3.2 specification control; SOP-2.3.4 Vendor Approval; SOP-2.3.2.3 Label Control.\nFSQM-012 Good Manufacturing Practices Program.\nFSQM-016 Food Safety Plan (HACCP) - Part 7, the hazard analysis.\nFSQM-018 Non-Conforming Product and Equipment; FSQM-019 Rework; FSQM-009 CAPA Program; FSQM-023 Product Withdrawal and Recall Program.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here.", "revision_history": "New - 2026-10-05 - DRAFT under D-23, for the Minor findings against 2.8.1.1, 2.8.1.2, 2.8.1.3, 2.8.1.5 and 2.8.1.6. The site had no allergen management program.\n\nOWNER'S ANSWERS (2026-10-05): the allergens on site are wheat, milk, egg, soy, pecans and other tree nuts; cakes with nuts are made last in the day; the changeover clean is checked by looking only, with no swab; staff eat and keep their food in a separate break area. The finished pack declares wheat, milk, egg and soy on every cake.\n\nSOP-204 Allergen Cleaning Procedure (a three-line draft, never issued) is REPLACED by this program and is archived when this program is issued. Its ATP swab does not show that an allergen is gone, which was the finding against 2.8.1.5. The changeover clean was already written, machine by machine, in SOP-901 to SOP-904, and recorded on FRM-909 to FRM-912. So there is no separate Allergen Changeover Log, and the number clash on FRM-204 goes away: FRM-204 stays the supplier evaluation checklist.\n\n2.8.1.4 was scored Compliant against SOP-204, so this program takes it over.\n\nNEW REQUIREMENT, NOT YET DONE: swabbing with an allergen test kit (validation, then every three months). The three-month interval is the site's choice and can be changed.\n\nAT ISSUE: archive SOP-204; add a three-monthly 'allergen cleaning verification' row to the verification schedule (FSQM-017 Part 6) against FRM-916.\n\nTO CONFIRM BEFORE ISSUE: (1) which tree nuts besides pecans, and in which products; (2) every material in use, including the nuts, the egg and the lubricants, entered on FRM-207 with its allergen statement; (3) the allergen list posted in the production room; (4) the nuts' own marked scoop and container, and their place on the allergen rack; (5) a test kit chosen that detects the nuts used, and the three validation cleans per machine recorded on FRM-916; (6) that there is no vending machine; (7) the machine cleaning logs FRM-909 to FRM-912 in use on changeover days; (8) TRN-003, TRN-004 and TRN-004A read against this program."}$q$::jsonb),
  ('FRM-916', 'Allergen Cleaning Verification Record', 'form', 'Module 2', 'draft', 'New',
   '2.8.1.5', true, jsonb_build_object('form_schema', $q${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{reason} - {date}"}, "sections": [{"id": "check", "title": "1. The check", "fields": [{"id": "how_this_works", "type": "info", "label": "How to use this", "text": "One record each time surfaces are swabbed for an allergen after a changeover clean (FSQM-027). Swab after the clean and before the equipment is used again. Validation is the first three changeover cleans on each machine; after that, one changeover clean on each machine at least every three months. Follow the test kit's own instructions, and attach a photo of each result."}, {"id": "reason", "type": "select", "label": "Reason", "width": "third", "required": true, "showInList": true, "options": ["Validation", "Three-monthly verification", "After a change to the clean, equipment or nut", "Re-test after a failed result"]}, {"id": "date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true}, {"id": "product_before", "type": "text", "label": "Product made before the clean", "width": "third", "required": true, "showInList": true}, {"id": "allergen", "type": "text", "label": "Allergen tested for", "width": "third", "required": true, "help": "The nut that was in the product, for example pecan"}, {"id": "kit", "type": "text", "label": "Test kit", "width": "third", "required": true, "help": "Maker and name"}, {"id": "kit_lot", "type": "text", "label": "Kit lot and expiry", "width": "third", "required": true}, {"id": "cleaning_log", "type": "text", "label": "Cleaning log for this clean", "width": "half", "help": "Which log and date - FRM-909, FRM-910, FRM-911 or FRM-912"}]}, {"id": "swabs", "title": "2. Swabs", "fields": [{"id": "swabs", "type": "grid", "label": "Surfaces swabbed", "required": true, "rowDialog": true, "columns": [{"id": "equipment", "label": "Equipment", "type": "select", "options": ["Mixer - bowl", "Mixer - paddle, whip or dough arm", "Kook-E-King depositor", "Beldos depositor", "Kettle", "Pans or molds", "Racks", "Table or work surface", "Scoop or utensil", "Other"], "required": true, "width": 1.5}, {"id": "surface", "label": "Where exactly", "type": "text", "required": true, "width": 2, "scanFact": "none"}, {"id": "result", "label": "Result", "type": "select", "options": ["Not detected", "DETECTED"], "required": true, "width": 1}, {"id": "notes", "label": "Notes", "type": "text", "width": 1.5, "scanFact": "none"}], "rows": {"mode": "dynamic", "min": 1, "addLabel": "Add swab"}}]}, {"id": "outcome", "title": "3. Result and actions", "fields": [{"id": "overall", "type": "select", "label": "Overall", "width": "half", "required": true, "showInList": true, "options": ["Pass - nothing detected", "Fail - allergen detected"]}, {"id": "actions", "type": "textarea", "label": "If detected: what was done", "help": "The re-clean and re-test, any product held on FRM-702, and what will change in the clean"}, {"id": "capa_no", "type": "text", "label": "CAPA Report no. (FRM-007)", "width": "third"}]}, {"id": "sign", "title": "4. Sign-off", "fields": [{"id": "completed_by", "type": "signature", "label": "Swabbed by", "role": "filler", "required": true, "statement": "The swabs were taken after the clean and before the equipment was used again, and the results are as shown."}, {"id": "reviewed_by", "type": "signature", "label": "Reviewed by the SQF Practitioner", "role": "verifier", "required": true, "statement": "I have reviewed this record and the actions taken."}]}]}$q$::jsonb));

do $verify$
declare p jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-027';
  if jsonb_array_length(p) <> 46 then raise exception 'FSQM-027 procedure is % lines, expected 46.', jsonb_array_length(p); end if;
  if (select count(*) from unnest(array['2.8.1.1 i)', '2.8.1.1 ii)', '2.8.1.1 iii)', '2.8.1.1 iv)', '2.8.1.1 v, vi)', '2.8.1.2)', '2.8.1.3)', '2.8.1.4)', '2.8.1.5)', '2.8.1.6)']) c where p::text like '%' || c || '%') <> 10 then
    raise exception 'FSQM-027 does not cite every limb of 2.8.1.';
  end if;
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-027', 'FRM-916')
              and content::text ~* 'Diana|Gabriela|Christina|GJM|Mercer|Pillsbury|Amazon|Sysco|Bahamas') then
    raise exception 'a D-23 document names a person, a supplier or a customer; controlled documents name positions.';
  end if;
  if (select count(*) from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
                           jsonb_array_elements(s->'fields') f where d.sop_number = 'FRM-916') <> 14 then
    raise exception 'FRM-916 field count is wrong.';
  end if;
  if (select status from public.sop_documents where sop_number = 'SOP-204') is distinct from 'draft' then
    raise exception 'SOP-204 was not meant to change here.';
  end if;
end $verify$;

commit;
